export function getDrivePreviewUrl(videoSrcOrFilename: string): string | null {
  const filename = videoSrcOrFilename.split('/').pop() || videoSrcOrFilename;
  const directId = DRIVE_VIDEO_IDS[filename] || DRIVE_VIDEO_IDS[filename.replace(/\s+/g, '')];
  if (directId) {
    return `https://drive.google.com/file/d/${directId}/preview`;
  }
  return null;
}

export function getDriveDirectFileUrl(videoSrcOrFilename: string): string | null {
  const filename = videoSrcOrFilename.split('/').pop() || videoSrcOrFilename;
  const directId = DRIVE_VIDEO_IDS[filename] || DRIVE_VIDEO_IDS[filename.replace(/\s+/g, '')];
  if (directId) {
    return `https://drive.google.com/file/d/${directId}/view?usp=sharing`;
  }
  return null;
}
